// GENERATED BY SYMPLRV3 — DO NOT EDIT
// a screen case mounts a navigator and fires every handler — see withTestTimeout
jest.setTimeout(30000);
import React from 'react';
import renderer, { act } from 'react-test-renderer';
import { NavigationContainer } from '@react-navigation/native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { SafeAreaProvider } from 'react-native-safe-area-context';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';

// A screen is mounted AS A ROUTE, not as a bare element. A screen that reads
// route params calls useRoute(), which throws "Couldn't find a route object"
// outside a navigator — so those screens could never be smoke-tested at all.
// This also renders them the way the app does.
const Stack = createNativeStackNavigator();

// A fixed notched-phone frame, so inset-dependent layout is exercised rather
// than collapsed to zero.
const TEST_METRICS = {
  frame: { x: 0, y: 0, width: 390, height: 844 },
  insets: { top: 47, left: 0, right: 0, bottom: 34 },
};

const qc = new QueryClient({ defaultOptions: { queries: { retry: false } } });

/**
 * Mount a screen inside its real providers, return what it rendered, unmount.
 * The caller owns the test declaration and the assertion.
 */
export function renderScreen(Screen: React.ComponentType): unknown {
  let tree: renderer.ReactTestRenderer;
  act(() => {
    tree = renderer.create(
      <QueryClientProvider client={qc}>
        <SafeAreaProvider initialMetrics={TEST_METRICS}>
          <NavigationContainer>
            <Stack.Navigator screenOptions={{ headerShown: false }}>
              <Stack.Screen name="__smoke" component={Screen} />
            </Stack.Navigator>
          </NavigationContainer>
        </SafeAreaProvider>
      </QueryClientProvider>,
    );
  });
  const json = tree!.toJSON();
  act(() => tree!.unmount());
  return json;
}

/**
 * The same sweep, with every field the screen rendered ANSWERED.
 *
 * A generated screen's conditionals are mostly `visibleWhen` gates reading the
 * form store, so one pass over an empty store only ever takes one side of each
 * — which is why line coverage ran well ahead of branch coverage. The keys are
 * the widget ids, which the first render already put in the tree as testIDs, so
 * this needs nothing from the design.
 */
export async function exerciseScreenFilled(
  Screen: React.ComponentType,
  /** The design's own field ids, which outlive any testID rewriting. */
  designFields: readonly string[] = [],
): Promise<{
  fired: number;
  threw: number;
  json: unknown;
}> {
  // require, not an import: every emitted module goes past the import pruner on
  // its way out, and a store touched only inside this function reads as unused
  const { useFormStore } = require('../../src/gen/features/formStore') as {
    useFormStore: {
      getState: () => {
        setValues: (fn: (s: Record<string, unknown>) => Record<string, unknown>) => void;
      };
    };
  };
  const first = await exerciseScreen(Screen);
  const ids = [
    ...new Set([
      ...designFields,
      ...[...JSON.stringify(first.json ?? null).matchAll(/"testID":"([^"]+)"/g)].map(
        (m) => m[1] as string,
      ),
    ]),
  ];
  // '123456', not a one-character placeholder: a field write is guarded by what
  // the design asked for, and the commonest guard on a generated screen is a
  // LENGTH: an early return on pinValue.length fronts every passcode effect,
  // so a single character skipped all of them. Six digits satisfy the length
  // checks and are still truthy for the plain gates.
  const answers = ['123456', 'x'];
  let last = { fired: 0, threw: 0, json: null as unknown };
  for (const answer of answers) {
    useFormStore.getState().setValues(() => Object.fromEntries(ids.map((id) => [id, answer])));
    try {
      // eslint-disable-next-line no-await-in-loop
      last = await exerciseScreen(Screen);
    } finally {
      useFormStore.getState().setValues(() => ({}));
    }
  }
  return last;
}

/** The same sweep with a GIVEN set of answers — see the per-screen GATES map. */
export async function exerciseScreenWith(
  Screen: React.ComponentType,
  values: Record<string, string>,
): Promise<{ fired: number; threw: number; json: unknown }> {
  const { useFormStore } = require('../../src/gen/features/formStore') as {
    useFormStore: {
      getState: () => {
        setValues: (fn: (s: Record<string, unknown>) => Record<string, unknown>) => void;
      };
    };
  };
  useFormStore.getState().setValues(() => ({ ...values }));
  try {
    return await exerciseScreen(Screen);
  } finally {
    useFormStore.getState().setValues(() => ({}));
  }
}

/** Every prop a generated screen can hand a handler to. */
const HANDLER_PROPS = [
  'onPress',
  'onLongPress',
  'onChange',
  'onChangeText',
  'onComplete',
  'onDone',
  'onSubmitEditing',
  'onFocus',
  'onBlur',
  'onValueChange',
  'onCancel',
  'onClose',
] as const;

/**
 * Mount a screen and INVOKE every handler it rendered.
 *
 * A render-only smoke test reaches the markup and nothing else, which is
 * exactly where a generated screen's uncovered lines are: the press that
 * navigates, the field write, the validation on submit, the countdown's
 * completion. Firing them needs no per-screen knowledge — the handlers are on
 * the tree — so this stays a fixed helper rather than something derived from
 * each design.
 *
 * Handlers are COLLECTED before any is fired: one of them may unmount the node
 * it lives on (a modal closing), and a live node reference cannot be read after
 * that. A handler that throws is recorded rather than failing the suite — the
 * assertion that matters is that the screen still stands afterwards, and a
 * screen whose press needs a native module absent under jest must not turn into
 * a red build for every app.
 */
export async function exerciseScreen(Screen: React.ComponentType): Promise<{
  fired: number;
  threw: number;
  json: unknown;
}> {
  let tree: renderer.ReactTestRenderer;
  act(() => {
    tree = renderer.create(
      <QueryClientProvider client={qc}>
        <SafeAreaProvider initialMetrics={TEST_METRICS}>
          <NavigationContainer>
            <Stack.Navigator screenOptions={{ headerShown: false }}>
              <Stack.Screen name="__smoke" component={Screen} />
            </Stack.Navigator>
          </NavigationContainer>
        </SafeAreaProvider>
      </QueryClientProvider>,
    );
  });
  // Mount effects are async AND often timed — a splash screen decides where to
  // navigate from inside a setTimeout, then an await chain. Draining microtasks
  // never reaches that, and waiting in real time would cost seconds per screen.
  // The clock is advanced only when the CALLER faked it: switching timer modes
  // inside this shared helper broke every suite that owns its own timers.
  // EIGHT turns, not one: a react-query result reaches the component through
  // several scheduling hops (fetch → cache write → observer notify → render →
  // effect), so a single drain leaves a query that has resolved but not yet been
  // seen by the code that branches on it.
  for (let i = 0; i < 8; i += 1) {
    // eslint-disable-next-line no-await-in-loop
    await act(async () => {
      // try/catch, NOT jest.isMockFunction(setTimeout): modern fake timers swap
      // the global for a sinon clock, which is not a jest mock — so the guard
      // that reads like the obvious one is never true. With real timers this
      // call simply throws and there is nothing to advance.
      try {
        jest.advanceTimersByTime(2000);
      } catch {
        /* real timers */
      }
      await Promise.resolve();
      await Promise.resolve();
    });
  }
  const collected: Array<[string, (...a: unknown[]) => void]> = [];
  for (const node of tree!.root.findAll(() => true, { deep: true })) {
    for (const prop of HANDLER_PROPS) {
      const fn = (node.props as Record<string, unknown>)[prop];
      if (typeof fn === 'function') collected.push([prop, fn as (...a: unknown[]) => void]);
    }
  }
  let fired = 0;
  let threw = 0;
  /**
   * TWO passes over the same mount, and the second is not redundant.
   *
   * setField has two halves: it writes the value AND deletes that field's stale
   * validation error. The delete is
   *   const { [id]: _drop, ...rest } = errors; return rest;
   * and it only runs when the field ALREADY has an error — so on a screen whose
   * submit validates, it is reachable only in this order: press submit (which
   * writes the errors), then write the fields (which clears them). One pass
   * fires handlers in whatever order the tree happens to hold them, so a text
   * input ahead of the submit button never sees an error to clear. Those two
   * lines per validated field were, measured, over half of everything still
   * uncovered on a generated screen.
   *
   * The pass index is not passed to the handlers: firing the identical list
   * again is the point, because what changed is the STORE, not the arguments.
   */
  // The second pass is WRITES ONLY.
  //
  // Firing everything twice was measured and was a net loss: it doubled ~1500
  // screen mounts' worth of presses, which timed suites out — and an aborted
  // suite contributes NO coverage, so the number fell from 74.8% to 71.1% while
  // the run went from 252s to 937s. The presses are the expensive half (each
  // starts a mutation, a navigation, an effect chain); the writes are nearly
  // free and are the only ones the error-clearing path needs.
  const WRITE_PROPS = new Set(['onChangeText', 'onChange']);
  for (let pass = 0; pass < 2; pass += 1) {
    for (const [prop, fn] of collected) {
      if (pass === 1 && !WRITE_PROPS.has(prop)) continue;
      // a plausible argument per shape: text for a text write, true for a
      // toggle — and a DIFFERENT text on the second pass, so a field whose
      // handler short-circuits on an unchanged value still writes.
      const arg =
        prop === 'onChangeText'
          ? pass === 0
            ? '1'
            : '123456'
          : prop === 'onChange'
            ? pass === 0
            : undefined;
      try {
        // AWAITED act: most of a screen's uncovered lines live in what a handler
        // STARTS, not in the handler itself — a fireAndForget continuation, an
        // awaited verifyPasscode, a .then that navigates or writes a field. The
        // synchronous form counts the press and never runs its consequences,
        // because it does not drain the microtask queue.
        // eslint-disable-next-line no-await-in-loop
        await act(async () => {
          fn(arg);
          await Promise.resolve();
        });
        fired += 1;
      } catch {
        threw += 1;
      }
    }
  }
  const json = tree!.toJSON();
  act(() => tree!.unmount());
  return { fired, threw, json };
}
